from flask import Flask, render_template_string, request

app = Flask(__name__)

@app.route("/post")
def post():
    title = request.GET.get("title")
    content = request.GET.get("content")

    html = """<h1>{}</h1>
              <div>{}</div>""".format(title, content)

    return render_template_string(html)
